export const meta = {
  name: 'chain-AAAB',
  description: 'RUN-1 stage 1: fix B3+B4 (books), F3 (report), B6 (cli), then verify all',
  phases: [{ title: 'Fix' }, { title: 'Verify' }],
}
const COMMON = args.common
const VERDICT = {
  type: 'object',
  properties: {
    verdicts: { type: 'array', items: { type: 'object', properties: {
      ticket: { type: 'string' }, passed: { type: 'boolean' }, evidence: { type: 'string' }, why: { type: 'string' },
      parked: { type: 'object', properties: { question: {type:'string'}, header: {type:'string', maxLength: 8},
        options: {type:'array', minItems: 2, maxItems: 4, items: {type:'object', properties: {label:{type:'string'}, does:{type:'string'}, hurts:{type:'string'}}}},
        recommended: {type:'string'}, default: {type:'string'}, reason: {enum: ['taste','fact','conflict']},
        genuine: {type:'boolean'}, gated: {type:'string'}, files: {type:'array', minItems: 1, items: {type:'string'}},
        done: {type:'string'}, stop: {enum: ['none','destructive','security','outside','scope','repro']} },
        required: ['question','header','options','default','reason','genuine','gated','files','stop'] },
    }, required: ['ticket', 'passed', 'evidence'] } },
  },
  required: ['verdicts'],
}
phase('Fix')
const reports = await parallel(args.items.map(it => () =>
  agent(COMMON + '\n\n' + it.prompt, { label: 'AAAB fix:' + it.key, phase: 'Fix' })))
phase('Verify')
const summary = args.items.map((it, i) => '### ' + it.key + '\nTASK:\n' + it.prompt + '\nFIXER REPORT:\n' + (reports[i] || '(agent returned nothing)')).join('\n\n')
const verdict = await agent(args.verify + '\n\nTickets: B3, B4, F3, B6 - one verdict each.\n\n' + summary,
  { label: 'AAAB verify:B3,B4,F3,B6', phase: 'Verify', schema: VERDICT })
return { reports, verdict }

